/** Live-map zones (0053). */
export type MapZoneKind =
  | 'cordon' | 'exclusion' | 'evacuation' | 'hazard' | 'search'
  | 'road_closure' | 'route' | 'staging' | 'command_post' | 'rendezvous'
  | 'last_seen' | 'note';
export type MapZoneShape = 'polygon' | 'circle' | 'line' | 'point';
export type MapZoneVisibility = 'private' | 'department' | 'departments' | 'incident' | 'everyone';

export type Silo = 'Ethekwini' | 'MetroPolice' | 'MetroFire' | 'Medical' | 'EthekwiniDisaster';

export type UserRole =
  | 'SystemAdmin' | 'SuperAdmin' | 'Admin' | 'Supervisor'
  | 'Dispatcher' | 'Operator' | 'ControlRoom' | 'IncidentLogger' | 'Viewer' | 'System'
  | 'Captain' | 'Police' | 'Officer' | 'Metro' | 'Security'
  | 'Chief' | 'FireChief' | 'Firefighter'
  | 'Paramedic' | 'Doctor'
  | 'Disaster' | 'CaseManager' | 'Citizen'
  | 'Responder' | 'Staff' | 'SystemController';

export type IncidentStatus =
  | 'New' | 'Pending' | 'Pending Dispatch' | 'Pending Analysis'
  | 'Dispatched' | 'En Route' | 'Arrived' | 'On Scene' | 'Transporting' | 'Active'
  | 'Closed' | 'Resolved';

export type IncidentSeverity = 'Low' | 'Medium' | 'High' | 'Critical';

/** Why an alert was raised — drives its icon and grouping. */
export type AlertKind =
  | 'assignment' | 'incident_new' | 'incident_update' | 'broadcast' | 'system' | 'info'
  // Police response (migrations 0039/0040): an open dispatch to on-duty
  // officers, and the call being accepted / resolved, told to command.
  | 'dispatch' | 'accepted' | 'resolved'
  // Assign / backup (0042) and an officer's SOS to dispatch and command (0043).
  | 'responding' | 'reassigned' | 'backup' | 'sos';

/** How forcefully an alert interrupts: a corner toast or a modal that blocks. */
export type AlertPresentation = 'toast' | 'modal';

export type ApparatusStatus =
  | 'Available' | 'In Use' | 'En Route' | 'On Scene'
  | 'Out of Service' | 'Maintenance' | 'Decommissioned';

